using System.Linq;using AntColony.Core;using AntColony.Units;using AntColony.Buildings;using AntColony.World;using UnityEngine;
public static class Handcart1115Status { public static string Main()=>"time="+GameCalendar.GameSeconds+" scale="+Time.timeScale+"\n"+string.Join("\n",CommanderRoster.Instance.Commanders.Select(c=>c.CommanderName+" pos="+c.Position+" build="+c.IsConstructing+" carry="+c.IsCarrying+" ready="+c.CanStartConstruction+" personal="+JsonUtility.ToJson(c.PersonalState)))+"\n"+string.Join("\n",SceneObjects.All<BuildingConstructionSite>().Select(s=>"work="+s.RemainingWork+" ready="+s.Ready+" needs="+string.Join(",",s.Needs.Select(n=>n.type+":"+n.delivered+"/"+n.need+" r"+n.reserved)))); }
